"""The C header of ABI v1: the generated file both sides of the boundary compile against.

In the rust slice `crates/ak-abi` IS the header, because both sides are Rust. Here the core
is Rust and the host is C++, so the header has to exist as C and it has to agree with
`ak-abi` structurally. It is emitted from the SAME functions the rust backend uses
(`rust_abi.group_fields`, `presence_bits`, `vtable_messages`, `slot_elem_rust`), imported
read-only, so a group layout cannot be restated differently on the two sides -- which is
ABI v1 section 10's whole point, and the failure mode it names is "a wrong value in a
field", the worst way to find it.

Section 10 also asks for the layouts to be EXPORTED AND ASSERTED. They are: this header
emits a `static_assert` on `sizeof` and on `offsetof` of every group member, so a
disagreement is a compile error on the host rather than a wrong byte on the wire, and
`ak_layout_check()` in the core re-asserts the same numbers at run time from the Rust side.
"""
import os
import re
import sys

from ir import loop_slots, slot_name, direct_fields
import rust_abi as RA
import cpp_layout
from cppnames import RUST_TO_C, abi_order_topo

HEAD = ("/* @generated by ffi/poc/cpp/gen/generate.py from ffi/schema/shapes.json."
        " Do not edit. */\n")


def cty(rust_ty):
    """The C spelling of one group member type, from the rust backend's own spelling."""
    if rust_ty in RUST_TO_C:
        return RUST_TO_C[rust_ty]
    if rust_ty in ("ak_str", "ak_span", "ak_blob"):
        return "struct " + rust_ty
    if rust_ty.startswith(("ak_efix_", "ak_dfix_", "ak_ufix_")):
        return "struct " + rust_ty
    raise NotImplementedError("no C spelling for group member type %r" % rust_ty)


def emit(ir):
    o = [HEAD, """
/* The C ABI of ffi/design/ABI-v1.md, version 1.
 *
 * Fixed part (sections 4, 5, 10) and per-message part (section 6's groups and vtables,
 * section 7's fixes). C99/C++11 clean: nothing here depends on the standard level, which
 * is the hard stop README section 5.1 puts on this slice.
 */
#ifndef AK_ABI_H
#define AK_ABI_H

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* ---- section 5: errors ---------------------------------------------------------- */
#define AK_OK                   0
#define AK_ALREADY_INITIALIZED  1
#define AK_ERR_HOST            (-1)
#define AK_ERR_MALFORMED       (-2)
#define AK_ERR_TRUNCATED       (-3)
#define AK_ERR_DEPTH           (-4)
#define AK_ERR_LIMIT           (-5)
#define AK_ERR_TRANSCODE       (-6)
#define AK_ERR_CAPACITY        (-7)
#define AK_ERR_INVALID_STATE   (-8)
#define AK_ERR_PANIC           (-9)
#define AK_ERR_UNINITIALIZED  (-10)
#define AK_ERR_ABI            (-11)

#define AK_ABI_VERSION 1u

/* ---- section 4: common vocabulary ------------------------------------------------ */

typedef int32_t (*ak_grow_fn)(void *sink, int32_t want, uint8_t **dst, int32_t *cap);
typedef int32_t (*ak_transcode_fn)(const void *src, size_t len,
                                   uint8_t *dst, int32_t cap,
                                   ak_grow_fn grow, void *sink);

/* Encode: a string or bytes field as DATA inside the group, never a call. `len` counts
 * SOURCE code units; for a C++ host holding std::string that is bytes. `tc == NULL` means
 * the field is ABSENT, which is how a group tells absent from present-and-empty. */
struct ak_str { const void *data; size_t len; ak_transcode_fn tc; };

/* ABI v1 section 8: a reserved `data` value meaning "this field is a direct argument of
 * the call". C++ never needs it (there is nothing to pin) and pays nothing for it. */
#define AK_STR_DIRECT ((const void *)(uintptr_t)1)

/* Decode: an OFFSET into the buffer the host handed in, plus a byte length. */
struct ak_span { uint32_t off, len, coder; };

/* Decision 11's unknown-field bag: two words, not three. */
struct ak_blob { const void *data; size_t len; };

struct ak_uspan { int64_t token; uint32_t off, len; };

#define AK_TOKEN_ROOT ((int64_t)-1)

typedef struct ak_enc_ctx ak_enc_ctx;
typedef struct ak_dec_ctx ak_dec_ctx;

typedef int32_t (*ak_loop_f)(ak_enc_ctx *ctx, const void *obj, int64_t token);
typedef void (*ak_unk_f)(ak_dec_ctx *ctx, void *obj, const struct ak_uspan *spans, int32_t n);
""".lstrip("\n")]

    # ---- per-message groups ------------------------------------------------------
    # The layout enumeration is NOT rebuilt here: it comes from `cpp_layout.facts`, the
    # same list the core's run-time export is generated from (README R10: sweep the rule,
    # do not restate it).
    layout_asserts = cpp_layout.facts(ir)
    for name in abi_order_topo(ir):
        m = ir.msg(name)
        bits = RA.presence_bits(m)
        for pre in ("e", "d", "u"):
            enc = pre != "d"
            sname = "ak_%sfix_%s" % (pre, name)
            fields = RA.group_fields(m, enc)
            if pre == "u":
                fields = [(fn, ty.replace("ak_efix_", "ak_ufix_")) for fn, ty in fields]
                fields = fields + [("unknown", "ak_blob")]
            o.append("/* %s group for `%s`.%s */" % (
                "Encode" if enc else "Decode", name,
                "  With the unknown-field bag (decision 11 candidate)." if pre == "u" else ""))
            o.append("struct %s {" % sname)
            for fname, ty in fields:
                o.append("  %s %s;" % (cty(ty), fname))
            o.append("  uint32_t presence;")
            o.append("};")
            for fname, b in bits.items():
                o.append("#define %s_PRESENT_%s (1u << %d)" % (sname.upper(), fname.upper(), b))
            o.append("")

    # ---- vtables ------------------------------------------------------------------
    for name in RA.vtable_messages(ir):
        slots = loop_slots(ir, name)
        o.append("/* Encode vtable for `%s`. %s */" %
                 (name, "Empty: nothing in this message needs a call."
                  if not slots else "One slot per field that could not ride in the group."))
        o.append("struct ak_evt_%s {" % name)
        if not slots:
            o.append("  /* Reserved: an empty struct has no defined size in C. */")
            o.append("  const void *_reserved;")
        for path, f in slots:
            o.append("  ak_loop_f loop_%s;" % slot_name(path))
            et = RA.elem_type(f)
            if et and loop_slots(ir, et):
                o.append("  const struct ak_evt_%s *elem_%s;" % (et, slot_name(path)))
        o.append("};")
        o.append("")
        o.append("/* Decode vtable for `%s` (the push family, ABI v1 section 7.1). */" % name)
        o.append("struct ak_dvt_%s {" % name)
        o.append("  void (*apply)(ak_dec_ctx *, void *, const struct ak_dfix_%s *);" % name)
        o.append("  ak_unk_f unknown;")
        for path, f in slots:
            sn = slot_name(path)
            dty, _ = RA.slot_elem_rust(f)
            et = RA.elem_type(f)
            batchable = not (et and not ir.msg(et).leaf)
            if et:
                o.append("  ak_unk_f unk_%s;" % sn)
            if batchable:
                o.append("  void (*add_%s)(ak_dec_ctx *, void *, int64_t, const %s *, int32_t);"
                         % (sn, cty(dty)))
            else:
                o.append("  int64_t (*new_%s)(ak_dec_ctx *, void *);" % sn)
                o.append("  void (*apply_%s)(ak_dec_ctx *, void *, int64_t, const struct ak_dfix_%s *);"
                         % (sn, et))
                for ipath, iff in loop_slots(ir, et):
                    idty, _ = RA.slot_elem_rust(iff)
                    iet = RA.elem_type(iff)
                    if iet and not ir.msg(iet).leaf:
                        raise NotImplementedError(
                            "a non-leaf element inside a non-leaf element (%s.%s)"
                            % (et, slot_name(ipath)))
                    o.append("  void (*add_%s_%s)(ak_dec_ctx *, void *, int64_t, const %s *, int32_t);"
                             % (sn, slot_name(ipath), cty(idty)))
        o.append("};")
        o.append("")

    # ---- entry points --------------------------------------------------------------
    o.append("/* ABI v1 section 6: what the host calls are PLAIN EXPORTS, not a table. */")
    for root in ir.roots:
        dargs = ", const uint8_t *direct, size_t direct_len" if direct_fields(ir, root) else ""
        o.append("intptr_t ak_encode_%s(const void *obj, ak_enc_ctx *ctx,"
                 " const struct ak_evt_%s *vt, const struct ak_efix_%s *fix%s);"
                 % (root, root, root, dargs))
        o.append("intptr_t ak_uencode_%s(const void *obj, ak_enc_ctx *ctx,"
                 " const struct ak_evt_%s *vt, const struct ak_ufix_%s *fix%s);"
                 % (root, root, root, dargs))
        o.append("int32_t ak_decode_%s(ak_dec_ctx *ctx, void *obj, const uint8_t *buf,"
                 " size_t len, const struct ak_dvt_%s *vt);" % (root, root))
    for et in sorted(RA.element_types(ir)):
        if ir.msg(et).leaf:
            o.append("int32_t ak_elem_%s(ak_enc_ctx *ctx, const struct ak_efix_%s *elems, int32_t n);"
                     % (et, et))
            o.append("int32_t ak_uelem_%s(ak_enc_ctx *ctx, const struct ak_ufix_%s *elems, int32_t n);"
                     % (et, et))
        else:
            o.append("int32_t ak_elemu_%s(ak_enc_ctx *ctx, const struct ak_efix_%s *elems,"
                     " int32_t n, int64_t tok0);" % (et, et))
            o.append("int32_t ak_uelemu_%s(ak_enc_ctx *ctx, const struct ak_ufix_%s *elems,"
                     " int32_t n, int64_t tok0);" % (et, et))
    o.append("int32_t ak_blob_run(ak_enc_ctx *ctx, const struct ak_str *elems, int32_t n);")
    for ty in ("i32", "i64", "f64", "u8"):
        o.append("int32_t ak_run_%s(ak_enc_ctx *ctx, const %s *p, size_t n);"
                 % (ty, RUST_TO_C[ty]))
    o.append("")
    o.append("""
/* ---- the fixed exports (sections 3, 4, 5) ---------------------------------------- */
uint32_t ak_abi_version(void);
ak_enc_ctx *ak_enc_ctx_new(void);
void ak_enc_ctx_free(ak_enc_ctx *);
void ak_enc_reset(ak_enc_ctx *);
int32_t ak_enc_take(ak_enc_ctx *, const uint8_t **ptr, size_t *len);
int32_t ak_enc_err(const ak_enc_ctx *);
ak_dec_ctx *ak_dec_ctx_new(void);
void ak_dec_ctx_free(ak_dec_ctx *);
void ak_fail(void *ctx, int32_t code, const uint8_t *msg, uint32_t msg_len);
int32_t ak_dec_err(const ak_dec_ctx *);
void ak_dec_err_reset(ak_dec_ctx *);
ak_transcode_fn ak_tc_utf8(void);
ak_transcode_fn ak_tc_utf8_trusted(void);
ak_transcode_fn ak_tc_utf8_simd(void);
ak_transcode_fn ak_tc_bytes(void);

/* README R5: counted in the CORE, so a call the optimiser removed is not counted. */
struct AkCounters {
  uint64_t forward, reverse, transcode, prefix_moves, prefix_bytes, grows;
};
void ak_enc_counters(const ak_enc_ctx *, struct AkCounters *out);
/* Counting build only: the HOST reports a reverse crossing the core cannot see, because
 * `ak_str.tc` may point into either image and the counter lives in the core. */
void ak_enc_count_reverse(ak_enc_ctx *);
void ak_enc_counters_reset(ak_enc_ctx *);
void ak_dec_counters(const ak_dec_ctx *, struct AkCounters *out);
void ak_dec_counters_reset(ak_dec_ctx *);
size_t ak_enc_site_moves(const ak_enc_ctx *, uint32_t *out, size_t cap);

/* The boundary priced on its own, in the same process and build as the arms. */
uint64_t ak_noop(uint64_t x);
uint64_t ak_noop_reverse(uint64_t (*f)(uint64_t), uint64_t x);
""".strip("\n"))
    o.append("")

    # ---- section 10: group layouts exported and asserted ---------------------------
    o.append("/* ABI v1 section 10 and obligation 12.3: group layouts asserted, not assumed.")
    o.append(" * A disagreement between #[repr(C)] and this header otherwise surfaces as a")
    o.append(" * wrong VALUE in a field. Asserted at compile time on the host side here, and")
    o.append(" * re-asserted from the Rust side at run time by ak_layout_check(). */")
    o.append("#ifdef __cplusplus")
    o.append("#define AK_SASSERT(c, m) static_assert(c, m)")
    o.append("#else")
    o.append("#define AK_SASSERT(c, m) typedef char ak_sa_##__LINE__[(c) ? 1 : -1]")
    o.append("#endif")
    o.append("")
    # ---- section 9: the RPC half's client options (R-D2) ----------------------------
    o.extend(_rpc_client_opts())
    o.append("/* Number of (struct, member) layout facts this header pins. */")
    n = sum(1 + len(ms) for _, ms in layout_asserts)
    o.append("#define AK_LAYOUT_FACTS %d" % n)
    o.append("")
    o.append("/* The core writes its own view of the same facts here; the host compares. */")
    o.append("size_t ak_layout_facts(uint32_t *out, size_t cap);")
    o.append("")
    o.append("#ifdef __cplusplus")
    o.append("} /* extern \"C\" */")
    o.append("#endif")
    o.append("#endif /* AK_ABI_H */")
    o.append("")

    # The host-side compile-time table lives in its own header so ak_abi.h stays C.
    tbl = [HEAD, "/* The layout facts, in the order ak_layout_facts() writes them. */",
           "#ifndef AK_LAYOUT_H", "#define AK_LAYOUT_H", "#include <cstddef>",
           "#include <cstdint>", "#include \"ak_abi.h\"", "",
           "static const uint32_t AK_LAYOUT_HOST[AK_LAYOUT_FACTS] = {"]
    names = [HEAD,
             "/* One name per fact, in the same order, so a disagreement can be NAMED and",
             " * not merely counted. Emitted as its own generated target and included by",
             " * `conformance.cpp`; it used to be appended to ak_layout.h, carry no banner",
             " * and be included by nothing. */",
             "#ifndef AK_LAYOUT_NAMES_H", "#define AK_LAYOUT_NAMES_H",
             "static const char *const AK_LAYOUT_NAMES[AK_LAYOUT_FACTS] = {"]
    for sname, members in layout_asserts:
        tbl.append("  (uint32_t)sizeof(struct %s)," % sname)
        names.append("  \"sizeof %s\"," % sname)
        for mem in members:
            tbl.append("  (uint32_t)offsetof(struct %s, %s)," % (sname, mem))
            names.append("  \"%s.%s\"," % (sname, mem))
    tbl.append("};")
    tbl.append("#endif")
    tbl.append("")
    names.append("};")
    names.append("#endif")
    names.append("")
    return "\n".join(o), "\n".join(tbl), "\n".join(names)


# ---- R-D2: `ak_client_opts`, rendered from the Rust declaration rather than restated ----
#
# `src/rpc_common.h` used to hand-declare this struct with 3 fields while the core read 6,
# so `max_send_message` and `tcp_nagle` were read past the end of the host's 12-byte
# object. The declaration is now taken from `poc/codec/crates/ak-abi/src/lib.rs`, the
# crate whose `ak_client_opts` the core asserts field by field against its own
# (`ak-core/src/rpc.rs`, the `const _` block), so a field added there makes `--check`
# report `include/ak_abi.h` STALE instead of leaving a host reading garbage.
#
# The offsets asserted below follow from repr(C) over fields that are all 4-byte scalars;
# anything else is REFUSED rather than laid out here, because a layout rule belongs in
# the shared generator (design/FIX-PLAN.md WP5), not in a slice.
AK_ABI_RS = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                         "..", "..", "codec", "crates", "ak-abi", "src",
                                         "lib.rs"))
_RPC_SCALAR = {"u32": "uint32_t", "i32": "int32_t"}


def rust_struct_fields(src, name):
    m = re.search(r"pub struct %s \{(.*?)\n\}" % re.escape(name), src, re.S)
    if not m:
        raise NotImplementedError("REFUSED: no `pub struct %s` in %s" % (name, AK_ABI_RS))
    fields = []
    for line in m.group(1).splitlines():
        line = line.strip()
        if not line or line.startswith("//"):
            continue
        f = re.match(r"pub (\w+): (\w+),$", line)
        if not f:
            raise NotImplementedError("REFUSED: cannot render %r of %s" % (line, name))
        fields.append((f.group(1), f.group(2)))
    return fields


def _rpc_client_opts():
    fields = rust_struct_fields(open(AK_ABI_RS).read(), "ak_client_opts")
    o = ["/* ---- section 9: the RPC half's client options -------------------------------",
         " * Rendered from `ak_client_opts` in poc/codec/crates/ak-abi/src/lib.rs, which the",
         " * core asserts field by field against the struct it reads (ak-core/src/rpc.rs).",
         " * Never hand-declare it in a host: R-D2 was a 3-field copy of a 6-field struct. */",
         "struct ak_client_opts {"]
    for fname, fty in fields:
        if fty not in _RPC_SCALAR:
            raise NotImplementedError("REFUSED: ak_client_opts.%s has type %r" % (fname, fty))
        o.append("  %s %s;" % (_RPC_SCALAR[fty], fname))
    o.append("};")
    o.append("#define AK_CLIENT_OPTS_FIELDS %d" % len(fields))
    o.append("AK_SASSERT(sizeof(struct ak_client_opts) == %d, \"sizeof ak_client_opts\");"
             % (4 * len(fields)))
    for i, (fname, _) in enumerate(fields):
        o.append("AK_SASSERT(offsetof(struct ak_client_opts, %s) == %d,"
                 " \"ak_client_opts.%s\");" % (fname, 4 * i, fname))
    o.append("")
    return o
